use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl StringTracker { pub fn new () -> Self { Self :: default () } # [doc = " Add an input string to track"] pub fn track_input (& mut self , content : & str , file : & str , line : usize , column : usize , byte_offset : usize) { let hash = hash_string (content) ; self . input_strings . insert (hash , StringRecord { content : content . to_string () , file : file . to_string () , line , column , byte_offset , byte_length : content . len () , }) ; } # [doc = " Add an output string to track"] pub fn track_output (& mut self , content : & str , file : & str , line : usize , column : usize , byte_offset : usize) { let hash = hash_string (content) ; self . output_strings . insert (hash , StringRecord { content : content . to_string () , file : file . to_string () , line , column , byte_offset , byte_length : content . len () , }) ; if self . input_strings . contains_key (& hash) { self . accounted_for . insert (hash) ; } } # [doc = " Verify all input strings are accounted for in output"] pub fn verify_complete (& self) -> Result < () , Vec < StringRecord > > { let mut missing = Vec :: new () ; for (hash , record) in & self . input_strings { if ! self . accounted_for . contains (hash) { let mut found = false ; for output_record in self . output_strings . values () { if output_record . content . contains (& record . content) { found = true ; break ; } } if ! found { missing . push (record . clone ()) ; } } } if missing . is_empty () { Ok (()) } else { Err (missing) } } # [doc = " Get summary statistics"] pub fn summary (& self) -> String { format ! ("StringTracker summary: {} input strings, {} output strings, {} accounted for" , self . input_strings . len () , self . output_strings . len () , self . accounted_for . len ()) } }